#include <bits/stdc++.h>
using namespace std;

bool check_property(const vector<int>& f, int p, int k) {
    for (int i = 0; i < p; ++i) {
        if (f[(k * i) % p] != (k * f[i]) % p) {
            return false;
        }
    }
    return true;
}

long long recursive_count(vector<int>& f, int p, int k, int i) {
    if (i == p) {
        return check_property(f, p, k) ? 1 : 0;
    }
    long long total = 0;
    for (int j = 0; j < p; ++j) {
        f.push_back(j);
        total += recursive_count(f, p, k, i + 1);
        f.pop_back();
    }
    return total;
}

long long main_function(int p, int k) {
    long long count = 0;
    unordered_set<int> visited;
    for (int j = 0; j < p; ++j) {
        if (visited.find(j) == visited.end()) {
            count++;
        }
        int current = j;
        while (visited.find(current) == visited.end()) {
            visited.insert(current);
            current = (current * k) % p;
        }
    }
    long long result = 1;
    for (int i = 0; i < count - (k != 1); ++i) {
        result = (result * p) % 1000000007;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, k;
    cin >> p >> k;
    cout << main_function(p, k) << "\n";
    return 0;
}

